import {createServer} from 'node:http'
import {mkdtemp,rm} from 'node:fs/promises'
import {tmpdir} from 'node:os'
import {join} from 'node:path'
import {createHost} from '../../src/host.js'
export async function subagentFixture(t,respond,configOverrides={}){
 const root=await mkdtemp(join(tmpdir(),'night-child-control-')),f={root,requests:[],handles:[],receipts:[],cleanup:[]};let host
 const server=createServer(async(req,res)=>{try{let raw='';for await(const c of req)raw+=c;const body=JSON.parse(raw);f.requests.push(body);const output=await respond?.(body,f)??{text:'child verified'};res.writeHead(200,{'content-type':'text/event-stream'});const send=(delta,finish_reason=null)=>res.write('data: '+JSON.stringify({id:'child-control',object:'chat.completion.chunk',model:'m',choices:[{index:0,delta,finish_reason}]})+'\n\n');if(output.tools){send({role:'assistant',tool_calls:output.tools.map((tool,index)=>({index,id:tool.id,type:'function',function:{name:tool.name,arguments:JSON.stringify(tool.args??{})}}))});send({},'tool_calls')}else{send({role:'assistant',content:output.text});send({},'stop')}res.end('data: [DONE]\n\n')}catch(error){res.writeHead(500);res.end(JSON.stringify({error:{message:error.message}}))}})
 t.after(async()=>{for(const fn of f.cleanup)fn();try{for(const receipt of f.receipts.toReversed())await receipt.dispose();for(const h of f.handles.toReversed())await h.dispose()}finally{try{await host?.close()}finally{await new Promise(r=>server.close(r));await rm(root,{recursive:true,force:true})}}});await new Promise(r=>server.listen(0,'127.0.0.1',r))
 host=f.host=await createHost({stateDir:join(root,'state'),workspaceDir:join(root,'work'),model:{provider:'fixture',model:'m'},providers:{fixture:{api:'openai-completions',apiKeyEnv:'FIXTURE_CHILD_CONTROL_KEY',baseURL:`http://127.0.0.1:${server.address().port}/v1`,retryPolicy:{mode:'normal',maxRetries:0},models:[{id:'m',input:['text','image'],contextWindow:16384,maxTokens:256}]}},...configOverrides},{environmentOptions:{cwd:root,home:root,inherited:{FIXTURE_CHILD_CONTROL_KEY:'fixture'}}})
 f.parent=async(id='control-parent')=>{const h=await host.ctx.agents.create({sessionId:id,agentOptions:{provider:'fixture',model:'m'},meta:{cwd:join(root,'work')},setup:async ctx=>{await host.ctx.agentPresets.mount(ctx,'night-bot')}});f.handles.push(h);return h.agent}
 f.start=async(parent,prompt='CHILD_INITIAL_MARKER',extra={})=>{const receipt=await host.ctx.subagents.startActivation({provider:'spawn',label:'fixture child',delivery:'caller',signal:new AbortController().signal,request:{parent,prompt:[{type:'text',text:prompt}],maxDepth:1},...extra});f.receipts.push(receipt);return receipt}
 f.events=async id=>{const r=await host.ctx.sessionPersistence.open(id,'read');try{return(await r.read()).events}finally{await r.close()}};return f
}
export async function eventually(predicate,timeout=4000){const until=Date.now()+timeout;for(;;){const value=await predicate();if(value)return value;if(Date.now()>until)throw new Error('fixture condition timed out');await new Promise(r=>setTimeout(r,5))}}
